 "content": "def transform(grid):
    """Copy the marked shape into every translated all-zero location."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    # The object color is the least frequent nonzero color.
    color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, _ in points)
    min_c = min(c for _, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    sh = max(r for r, _ in shape) + 1
    sw = max(c for _, c in shape) + 1
    out = [row[:] for row in grid]
    for top in range(h - sh + 1):
        for left in range(w - sw + 1):
            if all(grid[top + r][left + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[top + r][left + c] = color
    return out

if __name__ == '__main__':
    # Input grids can be passed as JSON on stdin for local verification.
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
